inline const Pov4BlockSchema* FindPov4BlockSchema(const char* word, size_t len)
{
    for (const Pov4BlockSchema& s : kPov4BlockSchemas)
        if ((std::strlen(s.word) == len) && (std::memcmp(s.word, word, len) == 0)) return &s;
    return nullptr;
}

